# frozen_string_literal: true

# Every route for the application. Owned by the integration lead: porting
# agents add controllers and views but do not edit this file.
Rails.application.routes.draw do
  ticker = { ticker: /[A-Za-z0-9.\-]+/ }

  root "dashboard#index"
  get "tokens.css", to: "tokens#show", as: :tokens_css, defaults: { format: :css }
  get "up", to: "rails/health#show", as: :rails_health_check

  get "research", to: "research#index", as: :research
  resources :documents, only: :show

  resources :companies, only: %i[index show], param: :ticker, constraints: ticker do
    member { post :pitchbook }
  end

  resources :pitchbooks, only: %i[index create show destroy] do
    member do
      post :rebuild
      post :comps
      post :assumptions
      post :reorder
      get :preview
      get :export
    end
    resources :evidences, only: :create
  end
  resources :slides, only: :update
  resources :evidences, only: :destroy

  get "monitor", to: "monitor#index", as: :monitor
  resources :watchlists, only: %i[create destroy] do
    resources :items, only: :create, controller: "watchlist_items"
    delete "items/:ticker", to: "watchlist_items#destroy", as: :item, constraints: ticker
  end
  resources :saved_searches, only: %i[create destroy]

  # JSON API with the same paths and keys as docs/api.md.
  namespace :api, defaults: { format: :json } do
    get "health", to: "system#health"
    get "export-formats", to: "system#export_formats"
    get "overview", to: "analytics#overview"
    get "trends", to: "analytics#trends"
    get "dashboard-charts", to: "analytics#dashboard_charts"
    get "search", to: "search#index"
    get "documents/:id", to: "documents#show"
    get "companies", to: "companies#index"
    get "companies/:ticker/suggest-comps", to: "companies#suggest_comps", constraints: ticker
    get "companies/:ticker/charts", to: "companies#charts", constraints: ticker
    get "companies/:ticker", to: "companies#show", constraints: ticker
    get "transactions", to: "transactions#index"
    post "ingest", to: "ingest#create"
    post "seed", to: "ingest#seed"
    get "watchlists", to: "watchlists#index"
    post "watchlists", to: "watchlists#create"
    post "watchlists/:id/items", to: "watchlists#add_items"
    delete "watchlists/:id/items/:ticker", to: "watchlists#remove_item", constraints: ticker
    delete "watchlists/:id", to: "watchlists#destroy"
    get "saved-searches", to: "saved_searches#index"
    post "saved-searches", to: "saved_searches#create"
    delete "saved-searches/:id", to: "saved_searches#destroy"
    get "alerts", to: "alerts#index"
    get "pitchbooks", to: "pitchbooks#index"
    post "pitchbooks", to: "pitchbooks#create"
    get "pitchbooks/:id", to: "pitchbooks#show"
    delete "pitchbooks/:id", to: "pitchbooks#destroy"
    post "pitchbooks/:id/rebuild", to: "pitchbooks#rebuild"
    post "pitchbooks/:id/comps", to: "pitchbooks#comps"
    post "pitchbooks/:id/assumptions", to: "pitchbooks#assumptions"
    post "pitchbooks/:id/evidence", to: "pitchbooks#add_evidence"
    post "pitchbooks/:id/reorder", to: "pitchbooks#reorder"
    get "pitchbooks/:id/valuation", to: "pitchbooks#valuation"
    get "pitchbooks/:id/valuation-charts", to: "pitchbooks#valuation_charts"
    get "pitchbooks/:id/preview", to: "pitchbooks#preview"
    get "pitchbooks/:id/export", to: "pitchbooks#export"
    match "slides/:id", to: "slides#update", via: %i[patch post]
    delete "evidence/:id", to: "evidences#destroy"
  end
end
